using Godot;
using System;
using System.Linq;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class StructureDefinitionOperations:RefCounted
{
    private readonly ActorDataOperations _data=new();private readonly ActorDefinitionOperations _definitions=new();private readonly ActorAnimationTrackOperations _tracks=new();private readonly DestructionDefinitionOperations _properties=new();private readonly StructureConnectionOperations _connections=new();
    private static Variant Get(Settings values,string key,Variant fallback=default)=>values.TryGetValue(key,out var value)?value:fallback;
    public void extend_actor(Resource definition){if(definition.Get("type_id").AsString() is not ("basic_shape" or "basic_mesh")||_definitions.find_property(definition,new StringName("structure_enabled"))!=null)return;_properties.add(definition,"structure_enabled","Enabled",false,"Structure",new Settings{["refresh_inspector"]=true},true);_properties.add(definition,"structure_role","Role",0,"Structure",new Settings{["choices"]=new GArray{"Dynamic element","Fixed foundation","Animated support"}},true);_properties.add(definition,"structure_iterations","Joint quality",12,"Structure",new Settings{["min"]=2,["max"]=32,["step"]=1},false);_properties.add(definition,"structure_overlay","Load overlay",true,"Structure",new Settings(),false);_properties.add(definition,"structure_connections","Connections",new Settings(),"Structure",new Settings{["structure_editor"]=true,["no_keyframes"]=true},false);}
    public Settings connection(string target,Vector3 pivot,Vector3 targetPivot,int kind)=>_connections.connection(target,pivot,targetPivot,kind);
    public void assign(WeakRef reference,GArray entries){using var value=reference.GetRef();if(value.AsGodotObject() is not RefCounted model)return;foreach(var item in entries){var entry=item.AsGodotDictionary();var actor=entry["actor"].As<Resource>();actor.Set("values",_data.copy_value(entry["values"]));actor.Get("animation_previews").AsGodotDictionary().Clear();if(entry.TryGetValue("tracks",out var saved)){var tracks=actor.Get("animation_tracks").AsGodotArray();tracks.Clear();foreach(var track in saved.AsGodotArray())tracks.Add(_tracks.copy_track(track.As<Resource>()));}actor.EmitChanged();}model.EmitSignal("changed");}
    public void commit(RefCounted model,GArray actors,GArray updates,string label){var before=new GArray();var after=new GArray();for(int i=0;i<actors.Count;i++){var actor=actors[i].As<Resource>();var values=actor.Get("values").AsGodotDictionary().Duplicate(true);values.Merge(updates[i].AsGodotDictionary(),true);var tracks=model.Call("animation_snapshot",actor).AsGodotArray();var retained=tracks.Duplicate();retained.Clear();var links=Get(values,"structure_connections",new Settings()).AsGodotDictionary();foreach(var item in tracks){var track=item.As<Resource>();var path=track.Get("path").AsStringArray();if(path.Length>1&&path[0]=="structure_connections"&&!links.ContainsKey(path[1]))continue;retained.Add(_tracks.copy_track(track));}before.Add(new Settings{["actor"]=actor,["values"]=_data.copy_value(actor.Get("values")),["tracks"]=tracks});after.Add(new Settings{["actor"]=actor,["values"]=values,["tracks"]=retained});}var action=new StructureConnectionsHistoryAction(model,before,after);var history=model.Get("history").As<UndoRedo>();history.CreateAction(label);history.AddDoMethod(new Callable(action,nameof(StructureConnectionsHistoryAction.restore_after)));history.AddUndoMethod(new Callable(action,nameof(StructureConnectionsHistoryAction.restore_before)));history.AddDoReference(action);history.CommitAction();}
    public void set_value(RefCounted model,Resource actor,string id,string key,Variant value,bool preview){var path=new[]{"structure_connections",id,key};if(_data.animation_track(actor,path)!=null){model.Call(preview?"preview_animation_value":"commit_animation_value",actor,path,value);return;}var links=_data.copy_value(_data.get_value(actor,"structure_connections",new Settings())).AsGodotDictionary();if(!links.ContainsKey(id))return;links[id].AsGodotDictionary()[key]=value;if(preview){actor.Get("values").AsGodotDictionary()[new StringName("structure_connections")]=links;actor.EmitChanged();model.EmitSignal("changed");}else commit(model,new GArray{actor},new GArray{new Settings{[new StringName("structure_connections")]=links}},"Edit structural connection");}
    public string connect_actors(RefCounted model,Resource a,Resource b,Vector3 point,Transform3D poseA,Transform3D poseB,int kind){string id=_data.new_id();var links=_data.copy_value(_data.get_value(a,"structure_connections",new Settings())).AsGodotDictionary();links[id]=connection(b.Get("id").AsString(),poseA.AffineInverse()*point,poseB.AffineInverse()*point,kind);string group=_data.get_value(a,"structure_assembly",_data.new_id()).AsString();commit(model,new GArray{a,b},new GArray{new Settings{[new StringName("structure_connections")]=links,[new StringName("structure_enabled")]=true,[new StringName("structure_assembly")]=group},new Settings{[new StringName("structure_enabled")]=true,[new StringName("structure_assembly")]=group}},"Connect structural elements");return id;}
    public void remap_actor(Resource actor,Settings ids,bool clearExternal){var links=_data.copy_value(_data.get_value(actor,"structure_connections",new Settings())).AsGodotDictionary();foreach(var value in links.Values){var link=value.AsGodotDictionary();string target=Get(link,"target","").AsString();link["target"]=Get(ids,target,clearExternal?"":target);}var values=actor.Get("values").AsGodotDictionary();values[new StringName("structure_connections")]=links;if(values.TryGetValue(new StringName("structure_assembly"),out var assembly))values[new StringName("structure_assembly")]=Get(ids,assembly.AsString(),actor.Get("id")).AsString();foreach(var value in actor.Get("animation_tracks").AsGodotArray()){var track=value.As<Resource>();var path=track.Get("path").AsStringArray();if(path.Length!=3||path[0]!="structure_connections"||path[2]!="target")continue;foreach(var keyValue in track.Get("keys").AsGodotArray()){var key=keyValue.As<Resource>();key.Set("value",Get(ids,key.Get("value").AsString(),clearExternal?Variant.From(""):key.Get("value")));}}}
    public Godot.Collections.Array<Settings> candidates(GArray actors,Settings bounds,double tolerance){var result=new Godot.Collections.Array<Settings>();for(int i=0;i<actors.Count;i++){var a=actors[i].As<Resource>();if(!bounds.TryGetValue(a.Get("id"),out var box))continue;var boxA=box.AsAabb();for(int j=i+1;j<actors.Count;j++){var b=actors[j].As<Resource>();if(!bounds.TryGetValue(b.Get("id"),out var other))continue;var boxB=other.AsAabb();var pa=boxB.GetCenter().Clamp(boxA.Position,boxA.End);var pb=pa.Clamp(boxB.Position,boxB.End);float gap=pa.DistanceTo(pb);if(gap<=tolerance)result.Add(new Settings{["a"]=a,["b"]=b,["point"]=(pa+pb)*.5f,["gap"]=gap});}}return result;}
}
